INSERT INTO feature VALUES('referent-reverse-index','editor','The reverse referent index','definition','implemented','ordinary',NULL,'For each declared name or binder, every use referring to it, read off the type table''s referent index once per held text; serves highlight, references and a binder''s rename. A held slot''s name in an access, an assignment or an element read refers to its binder, and so does a view''s name at its eliminator.','surface-dispatcher','crates/surface-dispatcher/src/typed/referent.rs crates/surface-lowering/src/lower/access.rs',NULL,NULL);
